  assert(!production_recipe_install_gate["install_started"], "C Runtime core recipe install gate must not start installation")
  assert(!production_recipe_install_gate["host_root_modified"], "C Runtime core recipe install gate must not mutate the host root")
  assert(!production_recipe_install_gate["backend_details_exposed"], "C Runtime core recipe install gate must hide backend details")
  assert(production_recipe_install_gate["desktop_safe_summary"] == "Recipe installation is blocked until trust requirements are satisfied.", "C Runtime core recipe install gate must expose blocked summaries")
  assert(!stdout.match?(/wine|prefix|\.wine|proton|virtual machine/i), "C Runtime core recipe install gate must not expose backend implementation terms")

  stdout, stderr, status = Open3.capture3(binary.to_s, "recipe-install-gate", "org.xnix.sample.notepad", "development")
  assert(status.success?, "C Runtime core development recipe install gate must exit successfully: #{stderr}")
  development_recipe_install_gate = JSON.parse(stdout)
  assert(development_recipe_install_gate["mode"] == "development", "C Runtime core recipe install gate must preserve development mode")
  assert(development_recipe_install_gate["decision"] == "allow", "C Runtime core recipe install gate must allow digest-verified development staging")
  assert(development_recipe_install_gate["blocking_reasons"].empty?, "C Runtime core development recipe install gate must not report blocking reasons")
  assert(development_recipe_install_gate["requirements"].empty?, "C Runtime core development recipe install gate must not report requirements")
  assert(development_recipe_install_gate["development_staging_allowed"], "C Runtime core recipe install gate must allow development staging")
  assert(!development_recipe_install_gate["production_install_allowed"], "C Runtime core development recipe install gate must not allow production install")
  assert(!development_recipe_install_gate["host_root_modified"], "C Runtime core development recipe install gate must not mutate the host root")

  stdout, stderr, status = Open3.capture3(binary.to_s, "recipe-install-gate", "org.xnix.unknown", "production")
  assert(status.success?, "C Runtime core unknown recipe install gate must emit a blocked model: #{stderr}")
  unknown_recipe_install_gate = JSON.parse(stdout)
  assert(unknown_recipe_install_gate["decision"] == "block", "C Runtime core unknown recipe install gate must block installation")
  assert(unknown_recipe_install_gate["matched_recipe"].nil?, "C Runtime core unknown recipe install gate must not report a match")
  assert(unknown_recipe_install_gate["blocking_reasons"].include?("recipe is not registered"), "C Runtime core unknown recipe install gate must explain registry misses")
  assert(!unknown_recipe_install_gate["request_object_created"], "C Runtime core unknown recipe install gate must not create request objects")
  assert(!unknown_recipe_install_gate["install_started"], "C Runtime core unknown recipe install gate must not start installation")

  _stdout, stderr, status = Open3.capture3(binary.to_s, "recipe-install-gate", "org.xnix.sample.notepad", "unknown")
  assert(!status.success?, "C Runtime core recipe install gate must reject unknown modes")
  assert(stderr.include?("mode must be development or production"), "C Runtime core recipe install gate must explain mode validation")

  stdout, stderr, status = Open3.capture3(binary.to_s, "write-gate", "Launch")
  assert(status.success?, "C Runtime core write-gate must exit successfully: #{stderr}")
  gate = JSON.parse(stdout)
  assert(gate["gate_type"] == "runtime-write-gate", "C Runtime core must emit write gate models")
  assert(gate["method_name"] == "Launch", "C Runtime core write gate must preserve the method")
  assert(gate["gate_decision"] == "blocked-until-production-backend", "C Runtime core must block writes until production backend")
  assert(!gate["write_method_enabled"], "C Runtime core must not enable writes")
  assert(!gate["dispatch_enabled"], "C Runtime core must not enable write dispatch")
  assert(!gate["request_object_created"], "C Runtime core must not create request objects")
  assert(!gate["execution_started"], "C Runtime core must not start execution")
  assert(gate["denial_error_name"] == "org.xnix.Compatibility1.Error.WriteMethodDisabled", "C Runtime core must expose the write denial error")

  _stdout, stderr, status = Open3.capture3(binary.to_s, "write-gate", "Unknown")
  assert(!status.success?, "C Runtime core must reject unknown write gate methods")
  assert(stderr.include?("reserved Runtime write method"), "C Runtime core must explain write gate validation")
end

